namespace simp {
namespace {

std::string llvmBytes(const std::string& bytes) {
    std::ostringstream escaped;
    for (const unsigned char byte : bytes) {
        if (byte >= 0x20 && byte <= 0x7e && byte != '"' && byte != '\\') {
            escaped << static_cast<char>(byte);
        } else {
            escaped << '\\' << std::uppercase << std::hex << std::setw(2) << std::setfill('0')
                    << static_cast<unsigned>(byte) << std::nouppercase << std::dec;
        }
    }
    return escaped.str();
}

} // namespace

std::string CodeGenerator::internString(const std::string& bytes) {
    const auto name = "@.simp.string." + std::to_string(nextString_++);
    stringGlobals_ += name + " = private unnamed_addr constant [" +
                      std::to_string(bytes.size()) + " x i8] c\"" + llvmBytes(bytes) + "\"\n";
    return name;
}

void CodeGenerator::emitStringBytes(const std::string& bytes) {
    if (bytes.empty()) return;
    const auto global = internString(bytes);
    const auto pointer = newTemporary();
    instructions_ += "  " + pointer + " = getelementptr inbounds [" +
                     std::to_string(bytes.size()) + " x i8], ptr " + global + ", i64 0, i64 0\n";
    const auto stream = newTemporary();
    instructions_ += "  " + stream + " = load ptr, ptr @stdout\n";
    instructions_ += "  call i64 @fwrite(ptr " + pointer + ", i64 1, i64 " +
                     std::to_string(bytes.size()) + ", ptr " + stream + ")\n";
}

void CodeGenerator::emitPrint(const Statement& statement) {
    if (statement.expressions.empty()) return;
    if (statement.expressions.size() > 1) {
        const auto& format = *statement.expressions.front();
        std::size_t segmentStart = 0;
        std::size_t argumentIndex = 1;
        for (std::size_t index = 0; index < format.value.size(); ++index) {
            if (format.value[index] != '{') continue;
            emitStringBytes(format.value.substr(segmentStart, index - segmentStart));
            const auto value = emitIntegerExpression(*statement.expressions[argumentIndex++]);
            instructions_ += "  call i32 (ptr, ...) @printf(ptr @.simp.int.format, i32 " +
                             value.operand + ")\n";
            index += 1;
            segmentStart = index + 1;
        }
        emitStringBytes(format.value.substr(segmentStart));
    } else {
        const auto value = emitExpression(*statement.expressions.front());
        if (value.type == "string") {
            const auto data = newTemporary();
            const auto length = newTemporary();
            instructions_ += "  " + data + " = extractvalue %SimpleString " + value.operand + ", 0\n";
            instructions_ += "  " + length + " = extractvalue %SimpleString " + value.operand + ", 1\n";
            const auto stream = newTemporary();
            instructions_ += "  " + stream + " = load ptr, ptr @stdout\n";
            instructions_ += "  call i64 @fwrite(ptr " + data + ", i64 1, i64 " + length +
                             ", ptr " + stream + ")\n";
        } else if (value.type == "int") {
            instructions_ += "  call i32 (ptr, ...) @printf(ptr @.simp.int.format, i32 " +
                             value.operand + ")\n";
        } else {
            unsupported(statement.location, "printing object references");
        }
    }
    emitStringBytes("\n");
}

} // namespace simp
